open Microsoft.Quantum.Logical;

function WinCondition (rst : Bool[], abc : Bool[]) : Bool {
    let p = Or(rst[0], Or(rst[1], rst[2])); 
    let u = Xor(abc[0], Xor(abc[1], abc[2]));
    return (p == u);
}

