open Microsoft.Quantum.Measurement;

operation QuantumStrategy (input : Bool, qubit : Qubit) : Bool {
    if input {
        let res = MResetX(qubit);
        return res == One;
    }
    else {
        let res = MResetZ(qubit);
        return res == One;
    }
}

operation QuantumStrategy (input : Bool, qubit : Qubit) : Bool {
    if input {
        H(qubit);
    }
    return M(qubit) == One;
}

